import{_ as t}from"./chunks/test.Cl0jF-I5.js";import{_ as o,c as r,o as a,ag as i}from"./chunks/framework.Bw-5EFTY.js";const f=JSON.parse('{"title":"Test Rules","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/gui/test-rules.md","filePath":"en/docs/gui/test-rules.md"}'),s={name:"en/docs/gui/test-rules.md"};function l(n,e,u,c,d,h){return a(),r("div",null,e[0]||(e[0]=[i('<h1 id="test-rules" tabindex="-1">Test Rules <a class="header-anchor" href="#test-rules" aria-label="Permalink to &quot;Test Rules&quot;">​</a></h1><p>Whistle provides convenient rule testing entry points to help you quickly verify how your rules match. You can access the test feature from:</p><ul><li><strong>Network list</strong>: Right-click menu → <code>Actions</code> → <code>Test Rules</code></li><li><strong>Create Rule dialog</strong>: <code>Preview Rules</code> → <code>Test</code></li><li><strong>Rules list</strong>: Right-click menu → <code>Actions</code> → <code>Test Rules</code></li></ul><p>With this feature, you can construct arbitrary requests and instantly check whether the current rule works as expected.</p><h2 id="interface-overview" tabindex="-1">Interface Overview <a class="header-anchor" href="#interface-overview" aria-label="Permalink to &quot;Interface Overview&quot;">​</a></h2><p><img src="'+t+'" alt="Test Rules"></p><h2 id="feature-descriptions" tabindex="-1">Feature Descriptions <a class="header-anchor" href="#feature-descriptions" aria-label="Permalink to &quot;Feature Descriptions&quot;">​</a></h2><h3 id="_1-rule-editor" tabindex="-1">1. Rule Editor <a class="header-anchor" href="#_1-rule-editor" aria-label="Permalink to &quot;1. Rule Editor&quot;">​</a></h3><ul><li>Used to enter the rule(s) to be tested.</li><li>The system automatically populates the editor with the currently selected rule (e.g., the matched rule, the rule from Preview, or the content from a Rules file). You can also edit manually.</li><li>Click the <strong>expand button</strong> in the bottom‑right corner to open a larger standalone window for editing complex rules.</li></ul><h3 id="_2-direct-mock-response-optional" tabindex="-1">2. Direct Mock Response (optional) <a class="header-anchor" href="#_2-direct-mock-response-optional" aria-label="Permalink to &quot;2. Direct Mock Response (optional)&quot;">​</a></h3><ul><li><strong>Default behaviour</strong>: When you click <code>Test</code>, the request goes directly to the live service.</li><li><strong>Enable this option</strong>: You can specify a response status code to simulate a server reply without actually hitting the live service. This is useful for quickly verifying rule logic.</li></ul><h3 id="_3-request-method" tabindex="-1">3. Request Method <a class="header-anchor" href="#_3-request-method" aria-label="Permalink to &quot;3. Request Method&quot;">​</a></h3><ul><li>Select the HTTP method (e.g., GET, POST, PUT, etc.) to match <code>method</code> conditions in your rules.</li></ul><h3 id="_4-request-url" tabindex="-1">4. Request URL <a class="header-anchor" href="#_4-request-url" aria-label="Permalink to &quot;4. Request URL&quot;">​</a></h3><ul><li>Enter the full request address (including protocol, domain, path, and query parameters) to test <code>url</code> matching logic.</li></ul><h3 id="_5-request-headers" tabindex="-1">5. Request Headers <a class="header-anchor" href="#_5-request-headers" aria-label="Permalink to &quot;5. Request Headers&quot;">​</a></h3><ul><li>Customise header fields (<code>Key: Value</code> format) to simulate specific header scenarios for rule matching.</li></ul><h3 id="_6-request-body-content" tabindex="-1">6. Request Body (Content) <a class="header-anchor" href="#_6-request-body-content" aria-label="Permalink to &quot;6. Request Body (Content)&quot;">​</a></h3><ul><li>Input request payload data (e.g., JSON, form data, etc.) for testing rules that depend on request body content (e.g., <code>includeFilter://b:pattern</code> conditions).</li></ul><h3 id="_7-test-button" tabindex="-1">7. Test Button <a class="header-anchor" href="#_7-test-button" aria-label="Permalink to &quot;7. Test Button&quot;">​</a></h3><ul><li>Click to initiate a simulated request based on your configuration. A dialog will pop up showing the match results (including matched rules, action types, and detailed information), helping you quickly locate issues or verify rule effectiveness.</li></ul>',21)]))}const q=o(s,[["render",l]]);export{f as __pageData,q as default};
